"""Tests for ``scripts/release.py`` — the release body generated by CI."""

import os
import tempfile
import unittest

from scripts import release


CHANGELOG = """# Changelog

版本号规则：MAJOR / MINOR / PATCH。

## v2.9.4

### 修复

- 第一条修复
- 第二条修复

### 构建与发布

- 构建镜像时自动创建 Release

## v2.9.3

### 修复

- 旧版本内容
"""


class ReadVersionTestCase(unittest.TestCase):
    def test_reads_the_real_package_version(self):
        version = release.read_version()

        # Sanity check the source of truth CI tags images and releases with.
        self.assertRegex(version, r"^\d+\.\d+\.\d+$")
        self.assertEqual(version.split(".")[0], "2")

    def test_missing_version_is_an_error(self):
        with tempfile.TemporaryDirectory() as tmp_dir:
            path = os.path.join(tmp_dir, "__init__.py")
            with open(path, "w", encoding="utf-8") as version_file:
                version_file.write("__license__ = 'MIT'\n")

            with self.assertRaises(ValueError):
                release.read_version(path)


class ExtractSectionTestCase(unittest.TestCase):
    def test_only_the_requested_section_is_returned(self):
        section = release.extract_section(CHANGELOG, "2.9.4")

        self.assertIn("第一条修复", section)
        self.assertIn("构建镜像时自动创建 Release", section)
        # The next version's bullets must not leak into the release body.
        self.assertNotIn("旧版本内容", section)
        self.assertNotIn("## v2.9.4", section)

    def test_unknown_version_is_an_error(self):
        # A tag that has no changelog section would publish an empty release.
        with self.assertRaises(ValueError) as caught:
            release.extract_section(CHANGELOG, "9.9.9")

        self.assertIn("9.9.9", str(caught.exception))

    def test_empty_section_is_an_error(self):
        changelog = "## v1.0.0\n\n## v0.9.0\n\n- 旧内容\n"

        with self.assertRaises(ValueError):
            release.extract_section(changelog, "1.0.0")

    def test_last_section_reads_to_end_of_file(self):
        section = release.extract_section(CHANGELOG, "2.9.3")

        self.assertEqual(section, "### 修复\n\n- 旧版本内容")


class RenderNotesTestCase(unittest.TestCase):
    def test_body_contains_changelog_and_pull_command(self):
        notes = release.render_notes(
            CHANGELOG,
            "2.9.4",
            image="ghcr.io/example/tg-dl",
            repo="example/tg-dl",
            platforms="linux/amd64,linux/arm64",
        )

        self.assertTrue(notes.startswith("### 修复"))
        self.assertIn("docker pull ghcr.io/example/tg-dl:2.9.4", notes)
        self.assertIn("`ghcr.io/example/tg-dl:2.9`", notes)
        self.assertIn("`ghcr.io/example/tg-dl:latest`", notes)
        self.assertIn("`linux/amd64`、`linux/arm64`", notes)
        self.assertIn(
            "https://github.com/example/tg-dl/blob/v2.9.4/CHANGELOG.md", notes
        )

    def test_empty_platforms_fall_back_to_amd64(self):
        notes = release.render_notes(CHANGELOG, "2.9.4", platforms=" , ")

        self.assertIn("`linux/amd64`", notes)

    def test_render_notes_uses_the_default_image(self):
        notes = release.render_notes(CHANGELOG, "2.9.4")

        self.assertIn(f"docker pull {release.DEFAULT_IMAGE}:2.9.4", notes)


class CliTestCase(unittest.TestCase):
    def test_print_version(self):
        with tempfile.TemporaryDirectory() as tmp_dir:
            version_file = os.path.join(tmp_dir, "__init__.py")
            with open(version_file, "w", encoding="utf-8") as handle:
                handle.write('__version__ = "1.2.3"\n')

            self.assertEqual(
                release.main(["--print-version", "--version-file", version_file]), 0
            )

    def test_output_file_is_written(self):
        with tempfile.TemporaryDirectory() as tmp_dir:
            changelog = os.path.join(tmp_dir, "CHANGELOG.md")
            output = os.path.join(tmp_dir, "notes.md")
            with open(changelog, "w", encoding="utf-8") as handle:
                handle.write(CHANGELOG)

            exit_code = release.main(
                [
                    "--version",
                    "2.9.4",
                    "--changelog",
                    changelog,
                    "--output",
                    output,
                ]
            )

            self.assertEqual(exit_code, 0)
            with open(output, encoding="utf-8") as handle:
                self.assertIn("第一条修复", handle.read())

    def test_unknown_version_exits_non_zero(self):
        with tempfile.TemporaryDirectory() as tmp_dir:
            changelog = os.path.join(tmp_dir, "CHANGELOG.md")
            with open(changelog, "w", encoding="utf-8") as handle:
                handle.write(CHANGELOG)

            # CI must fail loudly instead of publishing an empty release.
            self.assertEqual(
                release.main(["--version", "9.9.9", "--changelog", changelog]), 1
            )


if __name__ == "__main__":
    unittest.main()
